CREATE OR REPLACE FUNCTION calculate_cpi(
    hist_sign INTEGER,
    research_val INTEGER,
    cult_score INTEGER,
    conserve_status TEXT
) RETURNS NUMERIC AS $$
DECLARE
    status_val NUMERIC;
BEGIN
    -- Map conservation status to numeric value
    CASE LOWER(conserve_status)
        WHEN 'excellent' THEN status_val := 1;
        WHEN 'good' THEN status_val := 3;
        WHEN 'fair' THEN status_val := 5;
        WHEN 'poor' THEN status_val := 7;
        WHEN 'critical' THEN status_val := 10;
        ELSE status_val := 5;  -- default
    END CASE;

    RETURN ((hist_sign + research_val + cult_score) * (10 - status_val)) / 30.0;
END;
$$ LANGUAGE plpgsql;

